function maxFrequencyScore(nums, k) {
  const MOD = 1e9 + 7;
  const powers = new Map();
  let score = 0;
  let best = 0;

  for (let right = 0; right < nums.length; right++) {
    const value = nums[right];
    if (!powers.has(value)) {
      powers.set(value, []);
    }
    const stack = powers.get(value);
    const before = stack.length > 0 ? stack[stack.length - 1] : 0;
    const after = ((stack.length > 0 ? before : 1) * value) % MOD;
    stack.push(after);
    score = (score - before + after + MOD) % MOD;

    if (right >= k) {
      const leaving = powers.get(nums[right - k]);
      const removed = leaving.pop();
      const remaining = leaving.length > 0 ? leaving[leaving.length - 1] : 0;
      score = (score - removed + remaining + MOD) % MOD;
    }
    if (right >= k - 1) {
      best = Math.max(best, score);
    }
  }
  return best;
}

