function maxFrequencyScore(nums, k) {
  const MOD = 1000000007n;
  let best = 0n;
  for (let start = 0; start + k <= nums.length; start++) {
    const counts = new Map();
    for (let i = start; i < start + k; i++) counts.set(nums[i], (counts.get(nums[i]) || 0) + 1);
    let total = 0n;
    for (const [v, c] of counts) {
      let p = 1n;
      for (let t = 0; t < c; t++) p = (p * BigInt(v)) % MOD;
      total = (total + p) % MOD;
    }
    if (total > best) best = total;
  }
  return Number(best);
}

