function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(1500, 2000) : pick(1, 9);
  const poolSize = size === 'large' ? pick(1, 60) : pick(1, 4);
  const big = rand() < 0.5;
  const pool = Array.from({ length: poolSize }, () => big ? pick(1, 1000000) : pick(1, 6));
  if (rand() < 0.3) pool.push(1);
  const nums = Array.from({ length: n }, () => pool[Math.floor(rand() * pool.length)]);
  const k = rand() < 0.2 ? n : pick(1, n);
  return [nums, k];
}
